import {createServer} from 'node:http';
import {once} from 'node:events';
import {createHash} from 'node:crypto';
import {customerKhataFixture} from '../customer-khata-fixture';
import {createCustomerKhataHandler} from '../../supabase/functions/_shared/customer-khata-handler';
import {newInboxId} from '../../packages/core/inbox';
export async function startCustomerKhataService(){
 const f=await customerKhataFixture(process.cwd()),origin='http://127.0.0.1:4321',handler=createCustomerKhataHandler({store:{visit:f.visit},origins:new Set([origin])});let lose=false;
 const server=createServer(async(req,res)=>{try{const chunks:Buffer[]=[];let size=0;for await(const p of req){const b=Buffer.from(p);size+=b.length;if(size>32768)throw Error('Body too large');chunks.push(b);}const body=Buffer.concat(chunks),headers=new Headers();for(const[k,v]of Object.entries(req.headers))if(v!==undefined)headers.set(k,Array.isArray(v)?v.join(','):v);const response=await handler(new Request(apiUrl+req.url,{method:req.method,headers,...(body.length?{body:new Uint8Array(body)}:{})}));const bytes=Buffer.from(await response.arrayBuffer()),out=new Headers(response.headers);out.set('Content-Length',String(bytes.length));const drop=lose&&body.length>0&&JSON.parse(body.toString()).operation==='submit'&&response.ok;if(drop){lose=false;out.set('Connection','close');}res.writeHead(response.status,Object.fromEntries(out));res.end(drop?bytes.subarray(0,2):bytes);}catch{res.writeHead(500,{'Access-Control-Allow-Origin':origin,'Content-Type':'application/json'});res.end('{}');}});
 server.listen(0,'127.0.0.1');await once(server,'listening');const apiUrl='http://127.0.0.1:'+(server.address() as {port:number}).port;
 async function wallet(enabled=true){const context=await f.asRole<{settings:{revision:number}}>(1,'authenticated','select public.read_checkout_policy($1,null) data',[f.setup.outlet.id]);const wallets=enabled?[{id:newInboxId(),name:'bKash',phone:'+8801712345482',url:'https://wallet.example.invalid/pay'}]:[];await f.asRole(1,'authenticated','select public.change_checkout_policy($1,$2,\'submit\') data',[f.setup.outlet.id,JSON.stringify({v:1,id:newInboxId(),kind:'wallets',revision:context.settings.revision,orderId:null,orderRevision:null,wallets,enabled:null,maximum:null})]);}
 return {async prepare(){await f.seed();lose=false;await wallet();return {apiUrl,token:f.token};},async other(){return {apiUrl,...await f.otherAccount()};},wallet,loseNext(){lose=true;},async revoke(){await f.asRole(1,'authenticated','select public.revoke_public_link($1,$2) data',[f.linkId,newInboxId()]);},async counts(){return(await f.db.query<{data:{tasks:number;originals:number}}>("select json_build_object('tasks',(select count(*)::int from public.tasks),'originals',(select count(*)::int from private.customer_khata_actions)) data")).rows[0].data;},async financial(){const hash=createHash('sha256');for(const table of ['credit_accounts','credit_entries','sales','payments'])for(const row of(await f.db.query<{data:string}>('select row_to_json(t)::text data from public.'+table+' t order by id')).rows)hash.update(row.data);return hash.digest('hex');},async close(){server.closeAllConnections();await new Promise<void>((resolve,reject)=>server.close(e=>e?reject(e):resolve()));await f.db.close();}};
}
